-- CA-001C modular onboarding; no credentials, document bodies, or arbitrary executable schemas.
create table public.onboarding_templates(id uuid primary key default gen_random_uuid(),code text not null,version integer not null,name text not null,applies_to jsonb not null,module_references jsonb not null,completion_policy_code text not null,handoff_policy_code text not null,status text not null check(status in('draft','active','retired')),effective_from timestamptz not null,effective_until timestamptz,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(code,version),check(effective_until is null or effective_until>effective_from));
create table public.onboarding_module_definitions(id uuid primary key default gen_random_uuid(),code text not null,version integer not null,name text not null,product_family text,responsibility text not null check(responsibility in('customer','internal','shared','system')),completion_mode text not null,satisfies_requirement_codes text[] not null default '{}',prerequisite_module_codes text[] not null default '{}',composition_strategy text not null check(composition_strategy in('shared_once','once_per_product_family','once_per_property_context','once_per_commercial_engagement','repeatable')),field_schema_code text,validation_policy_code text,provisioning_action_code text,data_classification text not null check(data_classification in('standard','confidential','restricted')),skippable boolean not null,skip_policy_code text,status text not null check(status in('active','retired')),created_at timestamptz not null default now(),unique(code,version));
create table public.onboarding_cases(id uuid primary key,tenant_id uuid not null,customer_account_id uuid not null,source_type text not null check(source_type in('commercial_agreement','administrative_grant','migration','offer_expansion')),source_reference_id text not null,status text not null check(status in('pending','ready','in_progress','customer_action_required','internal_action_required','blocked','ready_for_provisioning','provisioning','ready_for_handoff','completed','cancelled')),plan_version integer not null,started_at timestamptz,completed_at timestamptz,cancelled_at timestamptz,current_module_instance_id uuid,blocker_code text,assigned_internal_owner_id uuid references public.profiles(id),idempotency_key_hash text not null unique,created_at timestamptz not null,updated_at timestamptz not null,revision integer not null default 1,foreign key(customer_account_id,tenant_id)references public.customer_accounts(id,tenant_id),unique(source_type,source_reference_id));
create table public.onboarding_plan_templates(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,onboarding_case_id uuid not null references public.onboarding_cases(id),template_code text not null,template_version integer not null,unique(onboarding_case_id,template_code,template_version));
create table public.onboarding_module_instances(id uuid primary key,onboarding_case_id uuid not null references public.onboarding_cases(id),tenant_id uuid not null,module_code text not null,module_version integer not null,product_family text,status text not null check(status in('locked','available','in_progress','submitted','changes_requested','verified','skipped','blocked','failed')),responsibility text not null check(responsibility in('customer','internal','shared','system')),required boolean not null,sequence integer not null,reused_from_module_instance_id uuid references public.onboarding_module_instances(id),started_at timestamptz,submitted_at timestamptz,verified_at timestamptz,completed_at timestamptz,blocked_by_code text,assigned_user_id uuid references public.profiles(id),revision integer not null default 1,unique(onboarding_case_id,module_code,product_family));
create table public.onboarding_submissions(id uuid primary key,tenant_id uuid not null,onboarding_case_id uuid not null references public.onboarding_cases(id),module_instance_id uuid not null references public.onboarding_module_instances(id),schema_code text not null,schema_version integer not null,submitted_by uuid not null references public.profiles(id),submitted_at timestamptz not null,data_classification text not null check(data_classification in('standard','confidential','restricted')),validation_status text not null check(validation_status in('pending','valid','invalid','requires_review')),validated_data jsonb not null,revision integer not null,unique(module_instance_id,revision));
create table public.onboarding_documents(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,onboarding_case_id uuid not null references public.onboarding_cases(id),module_instance_id uuid not null references public.onboarding_module_instances(id),storage_bucket text not null,storage_object_key text not null,content_type text not null,size_bytes bigint not null check(size_bytes>0 and size_bytes<=26214400),scan_status text not null check(scan_status in('pending','clean','rejected','unavailable')),uploaded_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),deleted_at timestamptz,unique(tenant_id,storage_bucket,storage_object_key),check(content_type in('image/jpeg','image/png','image/webp','application/pdf')));
create table public.onboarding_property_references(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,onboarding_case_id uuid not null references public.onboarding_cases(id),context_type text not null check(context_type in('hpm_property','guidebook_property','furnishing_project_property','investment_subject_property')),context_id uuid not null,relationship text not null check(relationship in('created','linked')),created_at timestamptz not null default now(),unique(onboarding_case_id,context_type,context_id));
create table public.onboarding_audit_events(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,onboarding_case_id uuid not null references public.onboarding_cases(id),module_instance_id uuid references public.onboarding_module_instances(id),event_type text not null,actor_id uuid,actor_type text not null check(actor_type in('customer','internal','system','migration')),reason_code text,customer_safe_message text,correlation_id text not null,idempotency_key_hash text unique,occurred_at timestamptz not null default now());
create table public.onboarding_notification_attempts(id uuid primary key default gen_random_uuid(),tenant_id uuid not null,onboarding_case_id uuid not null references public.onboarding_cases(id),recipient_user_id uuid not null references public.profiles(id),notification_type text not null,correlation_id text not null,idempotency_key_hash text not null unique,status text not null check(status in('queued','sent','failed')),attempt_count integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index onboarding_active_cases_idx on public.onboarding_cases(tenant_id,customer_account_id,status,updated_at);create index onboarding_internal_queue_idx on public.onboarding_module_instances(responsibility,status,assigned_user_id)where responsibility in('internal','shared');create index onboarding_blockers_idx on public.onboarding_cases(blocker_code,status)where blocker_code is not null;create index onboarding_review_queue_idx on public.onboarding_module_instances(status,submitted_at)where status='submitted';
create function public.prevent_published_onboarding_mutation()returns trigger language plpgsql set search_path='' as $$begin if old.status='active'then raise exception'Active onboarding definitions are immutable';end if;return new;end$$;create trigger onboarding_templates_immutable before update or delete on public.onboarding_templates for each row execute function public.prevent_published_onboarding_mutation();create trigger onboarding_modules_immutable before update or delete on public.onboarding_module_definitions for each row execute function public.prevent_published_onboarding_mutation();
alter table public.onboarding_templates enable row level security;alter table public.onboarding_module_definitions enable row level security;alter table public.onboarding_cases enable row level security;alter table public.onboarding_plan_templates enable row level security;alter table public.onboarding_module_instances enable row level security;alter table public.onboarding_submissions enable row level security;alter table public.onboarding_documents enable row level security;alter table public.onboarding_property_references enable row level security;alter table public.onboarding_audit_events enable row level security;alter table public.onboarding_notification_attempts enable row level security;
create policy "members read onboarding cases"on public.onboarding_cases for select to authenticated using(exists(select 1 from public.customer_account_memberships m where m.customer_account_id=onboarding_cases.customer_account_id and m.tenant_id=onboarding_cases.tenant_id and m.profile_id=auth.uid()and m.status='active'));
create policy "members read onboarding modules"on public.onboarding_module_instances for select to authenticated using(exists(select 1 from public.onboarding_cases c join public.customer_account_memberships m on m.customer_account_id=c.customer_account_id and m.tenant_id=c.tenant_id where c.id=onboarding_case_id and m.profile_id=auth.uid()and m.status='active'));
create policy "members read own onboarding submissions"on public.onboarding_submissions for select to authenticated using(exists(select 1 from public.onboarding_cases c join public.customer_account_memberships m on m.customer_account_id=c.customer_account_id and m.tenant_id=c.tenant_id where c.id=onboarding_case_id and m.profile_id=auth.uid()and m.status='active'));
create policy "admins read onboarding templates"on public.onboarding_templates for select to authenticated using(public.is_admin());create policy "admins read onboarding definitions"on public.onboarding_module_definitions for select to authenticated using(public.is_admin());create policy "admins read onboarding plan templates"on public.onboarding_plan_templates for select to authenticated using(public.is_admin());create policy "admins read onboarding documents"on public.onboarding_documents for select to authenticated using(public.is_admin());create policy "admins read onboarding references"on public.onboarding_property_references for select to authenticated using(public.is_admin());create policy "admins read onboarding audit"on public.onboarding_audit_events for select to authenticated using(public.is_admin());create policy "admins read onboarding notifications"on public.onboarding_notification_attempts for select to authenticated using(public.is_admin());
revoke all on public.onboarding_templates,public.onboarding_module_definitions,public.onboarding_cases,public.onboarding_plan_templates,public.onboarding_module_instances,public.onboarding_submissions,public.onboarding_documents,public.onboarding_property_references,public.onboarding_audit_events,public.onboarding_notification_attempts from anon;revoke insert,update,delete on public.onboarding_templates,public.onboarding_module_definitions,public.onboarding_cases,public.onboarding_plan_templates,public.onboarding_module_instances,public.onboarding_submissions,public.onboarding_documents,public.onboarding_property_references,public.onboarding_audit_events,public.onboarding_notification_attempts from authenticated;grant select on public.onboarding_cases,public.onboarding_module_instances,public.onboarding_submissions to authenticated;
